#include <map>
#include <string>
#include <vector>

class Inspector
{
public:
    void addObject(int id, std::map<std::string, double> fields) {}
    void select(std::vector<int> ids) {}
    std::string shown(const std::string& field) const { return ""; }
    void beginEdit(const std::string& field) {}
    void editValue(const std::string& field, double value) {}
    void endEdit() {}
    bool undo() { return false; }
    bool redo() { return false; }
    std::string undoLabel() const { return ""; }
    double value(int id, const std::string& field) const { return std::numeric_limits<double>::quiet_NaN(); }
    void markSaved() {}
    bool dirty() const { return false; }
};

solution.solution.cpp:
#include <cmath>
#include <limits>
#include <map>
#include <string>
#include <vector>

class Inspector
{
public:
    void addObject(int id, std::map<std::string, double> fields) { m_objects[id] = std::move(fields); }

    void select(std::vector<int> ids)
    {
        m_selected.clear();
        for (int id : ids) if (m_objects.count(id)) m_selected.push_back(id);
    }

    std::string shown(const std::string& field) const
    {
        bool any{ false };
        double first{ 0.0 };
        for (int id : m_selected)
        {
            const auto& f{ m_objects.at(id) };
            const auto it{ f.find(field) };
            if (it == f.end()) continue;
            if (!any) { first = it->second; any = true; }
            else if (it->second != first) return "--";
        }
        return any ? tidy(first) : "";
    }

    void beginEdit(const std::string& field)
    {
        m_editField = field;
        m_before.clear();
        for (int id : m_selected)
        {
            const auto& f{ m_objects.at(id) };
            const auto it{ f.find(field) };
            if (it != f.end()) m_before.push_back({ id, it->second });
        }
        m_editing = true;
    }

    void editValue(const std::string& field, double v)
    {
        const bool inDrag{ m_editing && field == m_editField };
        if (!inDrag) beginEdit(field);
        for (const auto& [id, before] : m_before) m_objects[id][field] = v;
        if (!inDrag) endEdit();
    }

    void endEdit()
    {
        if (!m_editing) return;
        m_editing = false;
        Step s{ m_editField, {} };
        bool changed{ false };
        for (const auto& [id, before] : m_before)
        {
            const double after{ m_objects[id][m_editField] };
            s.values.push_back({ id, before, after });
            if (after != before) changed = true;
        }
        m_before.clear();
        if (!changed) return;
        if (m_saved > m_position) m_saved = LOST;
        m_redo.clear();
        m_undo.push_back(std::move(s));
        ++m_position;
    }

    bool undo()
    {
        if (m_undo.empty()) return false;
        Step s{ m_undo.back() };
        m_undo.pop_back();
        for (const auto& v : s.values) m_objects[v.id][s.field] = v.before;
        m_redo.push_back(s);
        --m_position;
        return true;
    }

    bool redo()
    {
        if (m_redo.empty()) return false;
        Step s{ m_redo.back() };
        m_redo.pop_back();
        for (const auto& v : s.values) m_objects[v.id][s.field] = v.after;
        m_undo.push_back(s);
        ++m_position;
        return true;
    }

    std::string undoLabel() const
    {
        if (m_undo.empty()) return "";
        const Step& s{ m_undo.back() };
        std::string label{ "Undo Change " + s.field };
        if (s.values.size() > 1) label += " (" + std::to_string(s.values.size()) + " objects)";
        return label;
    }

    double value(int id, const std::string& field) const
    {
        const auto o{ m_objects.find(id) };
        if (o == m_objects.end()) return std::numeric_limits<double>::quiet_NaN();
        const auto f{ o->second.find(field) };
        return f == o->second.end() ? std::numeric_limits<double>::quiet_NaN() : f->second;
    }

    void markSaved() { m_saved = m_position; }
    bool dirty() const { return m_saved != m_position; }

private:
    struct Value { int id; double before; double after; };
    struct Step { std::string field; std::vector<Value> values; };

    static std::string tidy(double v)
    {
        std::string s{ std::to_string(v) };
        if (s.find('.') != std::string::npos)
        {
            while (!s.empty() && s.back() == '0') s.pop_back();
            if (!s.empty() && s.back() == '.') s.pop_back();
        }
        return s == "-0" ? "0" : s;
    }

    static constexpr long LOST = -1000000;
    std::map<int, std::map<std::string, double>> m_objects;
    std::vector<int> m_selected;
    bool m_editing{ false };
    std::string m_editField;
    std::vector<std::pair<int, double>> m_before;
    std::vector<Step> m_undo, m_redo;
    long m_position{ 0 };
    long m_saved{ 0 };
};

unitTests:
Inspector make() { Inspector i; i.addObject(1, { { "range", 10 }, { "intensity", 5 } }); i.addObject(2, { { "range", 12.5 }, { "intensity", 5 } }); i.addObject(3, { { "intensity", 1 } }); return i; }
TEST("shown values") { auto i = make(); i.select({ 1, 2, 3 }); CHECK_EQ(i.shown("range"), std::string("--")); i.select({ 1, 2 }); CHECK_EQ(i.shown("intensity"), std::string("5")); i.select({ 9 }); CHECK_EQ(i.shown("range"), std::string("")); }
TEST("a drag is one step") {
    auto i = make(); i.select({ 1 });
    i.beginEdit("range"); for (double v = 10; v <= 20; v += 1) i.editValue("range", v); i.endEdit();
    CHECK_NEAR(i.value(1, "range"), 20.0, 1e-9); CHECK_EQ(i.undoLabel(), std::string("Undo Change range"));
    CHECK(i.undo()); CHECK_NEAR(i.value(1, "range"), 10.0, 1e-9); CHECK(!i.undo());
}
TEST("many objects, each restored") {
    auto i = make(); i.select({ 1, 2, 3 });
    i.beginEdit("range"); i.editValue("range", 30); i.endEdit();
    CHECK_EQ(i.shown("range"), std::string("30")); CHECK_EQ(i.undoLabel(), std::string("Undo Change range (2 objects)"));
    i.select({ 3 }); i.undo();
    CHECK_NEAR(i.value(1, "range"), 10.0, 1e-9); CHECK_NEAR(i.value(2, "range"), 12.5, 1e-9); CHECK(std::isnan(i.value(3, "range")));
    i.redo(); CHECK_NEAR(i.value(2, "range"), 30.0, 1e-9);
}
TEST("no change, no step") { auto i = make(); i.select({ 1 }); i.beginEdit("intensity"); i.editValue("intensity", 7); i.editValue("intensity", 5); i.endEdit(); CHECK_EQ(i.undoLabel(), std::string("")); }
TEST("a click is its own step") { auto i = make(); i.select({ 1, 2 }); i.editValue("intensity", 9); CHECK_EQ(i.undoLabel(), std::string("Undo Change intensity (2 objects)")); i.undo(); CHECK_NEAR(i.value(2, "intensity"), 5.0, 1e-9); }
TEST("dirty") {
    auto i = make(); i.select({ 1 }); CHECK(!i.dirty());
    i.editValue("range", 11); CHECK(i.dirty()); i.markSaved(); CHECK(!i.dirty());
    i.editValue("range", 12); CHECK(i.dirty()); i.undo(); CHECK(!i.dirty());
    i.undo(); i.editValue("range", 99); CHECK(i.dirty()); i.undo(); CHECK(i.dirty());
}

